<?php require __DIR__.'/../layout.php'; ?><section class="card"><div class="top"><h2>Daftar Barang</h2><a class="btn" href="index.php?module=barang&action=form">+ Tambah Barang</a></div><div class="scroll"><table><thead><tr><th>ID</th><th>Nama</th><th>Kategori</th><th>Harga</th><th>Stok</th><th>Aksi</th></tr></thead><tbody><?php foreach($items as $row): ?><tr><td><?= (int)$row['id'] ?></td><td><?= htmlspecialchars($row['nama']) ?></td><td><?= htmlspecialchars($row['kategori']) ?></td><td>Rp <?= number_format($row['harga'],0,',','.') ?></td><td><?= (int)$row['stok'] ?></td><td><a href="index.php?module=barang&action=form&id=<?= (int)$row['id'] ?>">Edit</a> <form class="inline" method="post" action="index.php?module=barang&action=delete" onsubmit="return confirm('Hapus barang ini?')"><input type="hidden" name="csrf" value="<?= htmlspecialchars($_SESSION['csrf']) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="link danger">Hapus</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$items): ?><p>Belum ada barang.</p><?php endif; ?></section></main></div></body></html>
